solutionCode:
#include <iostream>
using namespace std;

class Shape {
public:
    virtual double area() = 0;
};

class Square : public Shape {
    double side;
public:
    Square(double s) : side(s) {}
    double area() override { return side * side; }
};

int main() {
    Square s(5);
    cout << s.area() << endl;
    return 0;
}

