solutionCode:
#include <iostream>
using namespace std;

class Animal {
public:
    virtual void speak() = 0;
    virtual ~Animal() {}
};

class Cat : public Animal {
public:
    void speak() override { cout << "Meow" << endl; }
};

class Dog : public Animal {
public:
    void speak() override { cout << "Woof" << endl; }
};

int main() {
    Animal* animals[2];
    animals[0] = new Cat();
    animals[1] = new Dog();
    for (int i = 0; i < 2; i++) {
        animals[i]->speak();
        delete animals[i];
    }
    return 0;
}
